CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL);
CREATE TABLE event_receipts(stream_id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), digest TEXT NOT NULL, PRIMARY KEY(stream_id,sequence));
CREATE TABLE stream_heads(stream_id TEXT PRIMARY KEY, sequence INTEGER NOT NULL CHECK(sequence>0));
CREATE TABLE characters(id TEXT PRIMARY KEY, observed_at INTEGER NOT NULL CHECK(observed_at>=0), json TEXT NOT NULL);
CREATE TABLE character_aliases(provisional_id TEXT PRIMARY KEY, verified_id TEXT NOT NULL REFERENCES characters(id));
CREATE TABLE play_sessions(id TEXT PRIMARY KEY, started INTEGER NOT NULL CHECK(started>=0), last_traffic INTEGER NOT NULL CHECK(last_traffic>=0), ended INTEGER CHECK(ended>=0), json TEXT NOT NULL);
CREATE TABLE runs(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES play_sessions(id), character_id TEXT REFERENCES characters(id), dungeon TEXT NOT NULL, started INTEGER NOT NULL CHECK(started>=0), ended INTEGER CHECK(ended>=0), completed_at INTEGER CHECK(completed_at>=0), died_at INTEGER CHECK(died_at>=0), outcome TEXT CHECK(outcome IN ('cleared','died','left','unknown')), complete_capture INTEGER NOT NULL CHECK(complete_capture IN (0,1)), entry_character_json TEXT, json TEXT NOT NULL);
CREATE TABLE run_evidence(run_id TEXT NOT NULL REFERENCES runs(id), ordinal INTEGER NOT NULL, at INTEGER NOT NULL CHECK(at>=0), kind TEXT NOT NULL, json TEXT NOT NULL, PRIMARY KEY(run_id,ordinal));
CREATE TABLE fights(id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), session_id TEXT NOT NULL REFERENCES play_sessions(id), started INTEGER NOT NULL CHECK(started>=0), ended INTEGER CHECK(ended>=0), boss_type INTEGER, local_dps REAL, complete_capture INTEGER NOT NULL CHECK(complete_capture IN (0,1)), json TEXT NOT NULL);
CREATE TABLE fight_players(fight_id TEXT NOT NULL REFERENCES fights(id), player_id TEXT NOT NULL, object_id INTEGER NOT NULL, damage REAL NOT NULL, dps REAL, rank INTEGER, json TEXT NOT NULL, PRIMARY KEY(fight_id,player_id));
CREATE TABLE damage_sources(fight_id TEXT NOT NULL, player_id TEXT NOT NULL, source_index INTEGER NOT NULL, item_type INTEGER, kind TEXT NOT NULL, damage REAL NOT NULL, hits INTEGER NOT NULL, json TEXT NOT NULL, PRIMARY KEY(fight_id,player_id,source_index), FOREIGN KEY(fight_id,player_id) REFERENCES fight_players(fight_id,player_id));
CREATE TABLE drops(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES play_sessions(id), run_id TEXT REFERENCES runs(id), at INTEGER NOT NULL CHECK(at>=0), bag_type INTEGER NOT NULL, bag_rank INTEGER, json TEXT NOT NULL);
CREATE TABLE drop_items(drop_id TEXT NOT NULL REFERENCES drops(id), slot INTEGER NOT NULL, item_type INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), json TEXT NOT NULL, PRIMARY KEY(drop_id,slot));
CREATE TABLE fame_samples(stream_id TEXT NOT NULL, sequence INTEGER NOT NULL, character_id TEXT NOT NULL REFERENCES characters(id), at INTEGER NOT NULL CHECK(at>=0), fame INTEGER NOT NULL, PRIMARY KEY(stream_id,sequence));
CREATE TABLE deaths(stream_id TEXT NOT NULL, sequence INTEGER NOT NULL, character_id TEXT REFERENCES characters(id), run_id TEXT REFERENCES runs(id), at INTEGER NOT NULL CHECK(at>=0), PRIMARY KEY(stream_id,sequence));
CREATE TABLE alerts(id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), at INTEGER NOT NULL CHECK(at>=0), kind TEXT NOT NULL, json TEXT NOT NULL);
CREATE TABLE timeline(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), at INTEGER NOT NULL CHECK(at>=0), kind TEXT NOT NULL, related_id TEXT, explanation TEXT NOT NULL);
CREATE INDEX runs_started ON runs(started,id);
CREATE INDEX runs_dungeon_outcome ON runs(dungeon,outcome,started,id);
CREATE INDEX runs_session ON runs(session_id,started,id);
CREATE INDEX fights_run ON fights(run_id,started,id);
CREATE INDEX fight_players_object ON fight_players(fight_id,object_id);
CREATE INDEX drops_run ON drops(run_id,at,id);
CREATE INDEX drops_session ON drops(session_id,at,id);
CREATE INDEX drops_bag ON drops(bag_type,at,id);
CREATE INDEX drop_items_type ON drop_items(item_type,drop_id);
CREATE INDEX fame_character ON fame_samples(character_id,at);
CREATE INDEX deaths_at ON deaths(at);
CREATE INDEX timeline_run ON timeline(run_id,at,id);
CREATE INDEX alerts_at ON alerts(at,id);
-- Additional query indexes; no additional data is retained.
CREATE INDEX runs_duration_ascending ON runs(coalesce((CASE WHEN ended>=started THEN ended-started END),9223372036854775807),id);
CREATE INDEX runs_duration_descending ON runs(coalesce((CASE WHEN ended>=started THEN ended-started END),-1),id);
CREATE INDEX runs_dungeon_started ON runs(dungeon,started,id);
CREATE INDEX runs_outcome_started ON runs(outcome,started,id);
CREATE INDEX timeline_related ON timeline(related_id,kind);
CREATE INDEX fights_session ON fights(session_id,started,id);
CREATE INDEX fights_started ON fights(started,id);
CREATE INDEX drops_at ON drops(at,id);
CREATE INDEX fame_at ON fame_samples(at,character_id);
